.darma-loader-tw-pulse-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: calc(var(--loader-size, 56px) * .1); width: var(--loader-size, 56px); height: var(--loader-size, 56px); }
.darma-loader-tw-pulse-grid span { border-radius: calc(var(--loader-size, 56px) * .16); background: var(--loader-color, #10b981); animation: darma-loader-tw-pulse-grid-twFade calc(var(--loader-speed, 1s) * 1.4) ease-in-out infinite; }
.darma-loader-tw-pulse-grid span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-tw-pulse-grid span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-tw-pulse-grid span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * .6); }
@keyframes darma-loader-tw-pulse-grid-twFade { 0%, 100% { opacity: 1; } 50% { opacity: .2; } }

